import './navigation.mjs';import {supabase,currentUser} from './auth-client.mjs';import {regularAt} from './schedule-model.mjs';
const $=id=>document.getElementById(id),fmt=n=>n.toLocaleString('en-US'),date=n=>new Intl.DateTimeFormat('en',{day:'numeric',month:'short',timeZone:'UTC'}).format(n);
const icons={'Fishing Contest':'fishingcontest.png','Cozy Farm':'cozyfarm.png','Treasure Hunt':'treasurehunt.png','Raft Race':'raftrace.png','Zobo Shooter':'zoboshooter.png'},styles={casual:'Casual',competitive:'Competitive',glitter:'Glitter Fruit'};
let events=[],plans={},editing=null,hasSearched=false,scheduleData,lastMatchScope,user,revision=0,offset=0;
function el(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;}
function status(text){$('match-status').textContent=text;}
async function rpc(name,args={}){const actor=await currentUser();if(!actor)throw Error('Log in to list plans and connect.');const {data,error}=await supabase.rpc(name,args);if(error)throw Error(['PGRST202','PGRST205','42P01'].includes(error.code)?'Matchmaking database setup is not complete yet.':error.message);if((await currentUser())?.id!==actor.id)throw Error('Account changed. Please retry.');return data;}
async function loadPlans(){try{user=await currentUser();plans={};if(user){for(const p of await rpc('my_event_match_plans'))plans[p.event+':'+Number(p.start)]=p;status('Listings expire when their event starts.');}else status('Log in and set your game UID in Account to list plans.');cards();}catch(e){status(e.message);cards();}}
function cards(){const list=$('event-list');list.replaceChildren();for(const event of events){const plan=plans[event.id],card=el('div',undefined,'plan-event-card'+(plan?' listed':'')),image=el('img');image.src='/assets/'+icons[event.name];image.alt='';card.append(image,el('strong',event.name),el('small',date(event.start)+' – '+date(event.end)));if(plan){const check=el('img',undefined,'listed-check');check.src='/matchmaking-assets/listed.png';check.alt='Listed';card.append(check,el('small',fmt(plan.min)+'–'+fmt(plan.max)+' pinballs · '+plan.slots+'/'+event.capacity+' open slots'));}const setting=el('button','Settings','secondary');setting.onclick=()=>settings(event);card.append(setting);if(plan){const find=el('button','Find Match','primary');find.onclick=()=>findMatches(event.id);const delist=el('button','Delist','delist');delist.onclick=async()=>{delist.disabled=true;try{await rpc('delist_event_match_plan',{p_event:event.name,p_start:new Date(event.start).toISOString()});await loadPlans();if(hasSearched)findMatches();}catch(e){status(e.message);}finally{delist.disabled=false;}};card.append(find,delist);}list.append(card);}$('find-all').disabled=!events.some(e=>plans[e.id]);}
function settings(event){if(!user){status('Log in and set your UID in Account first.');return;}editing=event;const p=plans[event.id]||{min:10000,max:30000,goal:'casual',slots:event.capacity,keys:4};$('settings-title').textContent=event.name;$('settings-date').textContent=date(event.start)+' – '+date(event.end)+' · UTC';$('budget-min').value=p.min;$('budget-max').value=p.max;$('goal').value=p.goal;styleText();const slots=$('my-slots');slots.replaceChildren();for(let n=1;n<=event.capacity;n++)slots.add(new Option(n+'/'+event.capacity+' · looking for '+n+' '+(n===1?'player':'players'),n));slots.value=p.slots;$('treasure-settings').hidden=event.name!=='Treasure Hunt';$('keys').value=p.keys;keyText();$('filter-error').hidden=true;$('plan-dialog').showModal();}
for(let n=1;n<=8;n++)$('keys').add(new Option(n+' '+(n===1?'key':'keys')+' · stage '+n*3+' completed',n));
function keyText(){$('key-explanation').textContent='If all four partnerships reach this target: '+Number($('keys').value)*4+' keys total. Keys describe shared progress, not each person’s individual contribution.';}$('keys').onchange=keyText;
$('plan-form').onsubmit=async e=>{e.preventDefault();if(editing.start<=Date.now()){$('plan-dialog').close();refreshEvents();return;}const min=Number($('budget-min').value),max=Number($('budget-max').value);if(!Number.isInteger(min)||!Number.isInteger(max)||min<0||max>1000000||min>max){$('filter-error').textContent='Minimum pinballs must not exceed maximum.';$('filter-error').hidden=false;return;}e.submitter.disabled=true;try{await rpc('save_event_match_plan',{p_event:editing.name,p_start:new Date(editing.start).toISOString(),p_min:min,p_max:max,p_style:$('goal').value,p_slots:Number($('my-slots').value),p_keys:Number($('keys').value),p_consent:true});await loadPlans();$('plan-dialog').close();$('match-summary').textContent='Plan listed. Select Find Match.';if(hasSearched)findMatches();}catch(err){$('filter-error').textContent=err.message;$('filter-error').hidden=false;}finally{e.submitter.disabled=false;}};
async function findMatches(only,more=false){lastMatchScope=only;hasSearched=true;if(!more)offset=0;const token=++revision,stylesSelected=[...document.querySelectorAll('.match-style-filters input:checked')].map(i=>i.value),list=$('player-list');list.setAttribute('aria-busy','true');$('find-all').disabled=true;try{const rows=await rpc('find_event_matches',{p_event:only?events.find(e=>e.id===only)?.name:null,p_styles:stylesSelected,p_offset:offset});if(token!==revision)return;list.replaceChildren();const listed=events.filter(e=>plans[e.id]&&(!only||e.id===only));$('match-summary').textContent=listed.length?'Compatible plans for your listed events.':'List an event plan to find matches.';for(const event of listed){const group=el('section',undefined,'match-event-group'),heading=el('div',undefined,'match-event-heading'),icon=el('img');icon.src='/assets/'+icons[event.name];icon.alt='';heading.append(icon,el('span',event.name),el('small',date(event.start)+' · UTC'));group.append(heading);const matches=rows.filter(p=>p.event===event.name&&Number(p.start)===event.start);if(!matches.length)group.append(el('div','No matching players on this page. Try other styles or adjust your plan.','empty-state'));for(const p of matches){const row=el('div',undefined,'player-row'),name=el('div',undefined,'player-name');name.append(el('span',p.name[0],'player-avatar'),el('strong',p.name));const budget=el('div');budget.append(el('strong',fmt(p.min)+'–'+fmt(p.max)),el('small','Planned pinballs'));const goal=el('div');goal.append(el('strong',styles[p.goal]),el('small',p.slots+'/'+event.capacity+' open slots'));if(event.name==='Treasure Hunt')goal.append(el('span',p.keys+' keys per partnership','key-badge'));const button=el('button','Connect','secondary');button.onclick=()=>view(event,p);row.append(name,budget,goal,button);group.append(row);}list.append(group);}const pages=el('div',undefined,'find-match-action');if(offset){const prev=el('button','Previous','secondary');prev.onclick=()=>{offset=Math.max(0,offset-100);findMatches(only,true);};pages.append(prev);}if(rows.length===100){const next=el('button','Next','secondary');next.onclick=()=>{offset+=100;findMatches(only,true);};pages.append(next);}list.append(pages);}catch(e){if(token===revision){list.replaceChildren();$('match-summary').textContent=e.message;}}finally{if(token===revision){list.setAttribute('aria-busy','false');$('find-all').disabled=!Object.keys(plans).length;}}}
async function view(event,p){$('dialog-name').textContent=p.name;const box=$('dialog-content');box.replaceChildren(el('p','Loading contact…'));$('player-dialog').showModal();try{const c=await rpc('event_match_contact',{p_partner:p.id,p_event:event.name,p_start:new Date(event.start).toISOString()});const budget=el('div',undefined,'connect-budget'),icon=el('img');icon.src='/guide-assets/fishing/pinball.png';icon.alt='';budget.append(icon,el('strong',fmt(c.min)+' – '+fmt(c.max)+' Pinballs'));const copy=el('button','Copy UID','secondary');copy.onclick=async()=>{try{await navigator.clipboard.writeText(c.uid);copy.textContent='UID copied';}catch{copy.textContent='Select and copy UID above';}};box.replaceChildren(el('p',c.uid,'connect-uid'),budget,el('p',styles[c.goal],'connect-style'),copy);}catch(e){box.replaceChildren(el('p',e.message));}}
$('find-all').onclick=()=>findMatches();for(const checkbox of document.querySelectorAll('.match-style-filters input'))checkbox.onchange=()=>{if(hasSearched)findMatches(lastMatchScope);};for(const d of document.querySelectorAll('dialog'))for(const b of d.querySelectorAll('.close,.close-action'))b.onclick=()=>d.close();
function refreshEvents(){if(!scheduleData)return;const now=Date.now();let removed=false;for(const id of Object.keys(plans)){const start=Number(id.slice(id.lastIndexOf(':')+1));if(!Number.isFinite(start)||start<=now){delete plans[id];removed=true;}}if(removed)loadPlans();const next=[];let cursor=regularAt(now,scheduleData.events.regular).end;while(next.length<5){const e=regularAt(cursor,scheduleData.events.regular);if(!next.some(x=>x.name===e.name))next.push({...e,id:e.name+':'+e.start,capacity:e.name==='Treasure Hunt'?4:3});cursor=e.end;}const changed=next.map(e=>e.id).join()!==events.map(e=>e.id).join();events=next;if(changed||removed){$('player-dialog').close();$('dialog-content').replaceChildren();cards();if(hasSearched)findMatches();}}
try{const response=await fetch('/data.json');if(!response.ok)throw Error('Schedule unavailable');scheduleData=await response.json();refreshEvents();await loadPlans();setInterval(refreshEvents,30000);window.addEventListener('focus',refreshEvents);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshEvents();});}catch{$('event-list').textContent='Could not load the event schedule. Refresh to try again.';$('event-list').setAttribute('role','alert');$('find-all').disabled=true;}

function styleText(){const descriptions={casual:'Plans to stay within the listed pinball budget.',competitive:'Willing to spend more if needed to reach the agreed goal.',glitter:'High-spend play focused on Glitter Fruit rewards.'};$('style-description').textContent=descriptions[$('goal').value];}$('goal').onchange=styleText;styleText();

supabase.auth.onAuthStateChange(()=>{revision++;plans={};$('player-dialog').close();$('plan-dialog').close();$('dialog-content').replaceChildren();$('player-list').replaceChildren();hasSearched=false;setTimeout(loadPlans,0);});
